17	package org.springframework.samples.petclinic.rest.controller;
18	
19	import java.time.LocalDate;
20	import java.util.Locale;
21	import java.util.Set;
22	import java.util.regex.Pattern;
23	
24	import org.slf4j.Logger;
25	import org.slf4j.LoggerFactory;
26	import org.springframework.http.HttpHeaders;
27	import org.springframework.http.HttpStatus;
28	import org.springframework.http.ResponseEntity;
29	import org.springframework.samples.petclinic.mapper.OwnerMapper;
30	import org.springframework.samples.petclinic.model.Owner;
31	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
32	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
33	import org.springframework.samples.petclinic.service.ClinicService;
34	import org.springframework.samples.petclinic.util.HashUtils;
35	import org.springframework.samples.petclinic.util.IdentityUtils;
36	import org.springframework.stereotype.Component;
37	import org.springframework.web.util.UriComponentsBuilder;
38	
39	/**
40	 * Owns the owner-creation concern: the single place that turns a submitted
41	 * {@link OwnerFieldsDto} into a validated, normalized, enriched and persisted {@link Owner},
42	 * and reports the create outcome as the HTTP response the endpoint returns.
43	 *
44	 * <p>Keeping the whole create pipeline here means every rule that fires on create — the
45	 * registration-date and business-day handling, the per-day and per-city quotas, the
46	 * address/telephone/email/postcode normalization and validation, the household, duplicate
47	 * and soft-match identity rules, and the derived customer code, namesake count and
48	 * membership number — reads the one owner this class builds, in the one order it applies
49	 * them, so they can never drift apart. The controller is left holding only the endpoint's
50	 * HTTP boundary.
51	 */
52	@Component
53	public class OwnerRegistrar {
54	
55	    /** Minimal syntactic check for an email address: a non-empty local part, a single
56	     *  '@', and a dotted domain, none containing whitespace or a second '@'. */
57	    private static final Pattern EMAIL_PATTERN =
58	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
59	
60	    /** A postcode, when supplied, must be exactly four digits before its region range is checked. */
61	    private static final Pattern POSTCODE_PATTERN = Pattern.compile("^[0-9]{4}$");
62	
63	    /** Disposable email domains that are rejected: an owner whose email domain matches one of
64	     *  these (case-insensitively) is refused with 400. */
65	    private static final java.util.Set<String> DISPOSABLE_EMAIL_DOMAINS =
66	        java.util.Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
67	
68	    /** Dedicated audit logger; emits an audit line on successful owner create. */
69	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
70	
71	    private final ClinicService clinicService;
72	
73	    private final OwnerMapper ownerMapper;
74	
75	    private final TelephoneNormalizer telephoneNormalizer;
76	
77	    private final AddressNormalizer addressNormalizer;
78	
79	    private final CityRegionResolver cityRegionResolver;
80	
81	    private final HouseholdResolver householdResolver;
82	
83	    /**
84	     * Remembers, per {@code Idempotency-Key}, the id of the owner that key's create originally
85	     * produced, so a later create carrying the same key returns that same owner instead of
86	     * creating a duplicate. The registrar is a singleton, so this store outlives a single
87	     * request; entries are keyed by the client-supplied key, which is expected to be unique
88	     * per logical create.
89	     */
90	    private final java.util.concurrent.ConcurrentHashMap<String, Integer> idempotencyKeys =
91	        new java.util.concurrent.ConcurrentHashMap<>();
92	
93	    public OwnerRegistrar(ClinicService clinicService,
94	                          OwnerMapper ownerMapper,
95	                          TelephoneNormalizer telephoneNormalizer,
96	                          AddressNormalizer addressNormalizer,
97	                          CityRegionResolver cityRegionResolver,
98	                          HouseholdResolver householdResolver) {
99	        this.clinicService = clinicService;
100	        this.ownerMapper = ownerMapper;
101	        this.telephoneNormalizer = telephoneNormalizer;
102	        this.addressNormalizer = addressNormalizer;
103	        this.cityRegionResolver = cityRegionResolver;
104	        this.householdResolver = householdResolver;
105	    }
106	
107	    /**
108	     * Validate, normalize, enrich and persist a new owner from the submitted fields, and
109	     * report the outcome as the response the create endpoint returns: {@code 201 Created}
110	     * (with a {@code Location} header and the created owner) on success, or the appropriate
111	     * rejection status ({@code 400}, {@code 409} or {@code 429}) when a create rule refuses
112	     * the request. No owner is persisted unless every rule passes.
113	     *
114	     * @param ownerFieldsDto the submitted owner fields
115	     * @return the create outcome as an HTTP response
116	     */
117	    public ResponseEntity<OwnerDto> register(OwnerFieldsDto ownerFieldsDto) {
118	        return register(ownerFieldsDto, null);
119	    }
120	
121	    /**
122	     * As {@link #register(OwnerFieldsDto)}, but honouring an optional {@code Idempotency-Key}.
123	     * When {@code idempotencyKey} is non-blank and a create with that key has already succeeded,
124	     * the owner it originally produced is returned with {@code 200 OK} instead of creating a
125	     * duplicate. Otherwise the normal create pipeline runs and, on success, the key is recorded
126	     * against the created owner so a later repeat resolves to the same owner.
127	     *
128	     * @param ownerFieldsDto the submitted owner fields
129	     * @param idempotencyKey the request's {@code Idempotency-Key} header, or {@code null} when absent
130	     * @return the create outcome as an HTTP response
131	     */
132	    public ResponseEntity<OwnerDto> register(OwnerFieldsDto ownerFieldsDto, String idempotencyKey) {
133	        String key = (idempotencyKey == null || idempotencyKey.isBlank()) ? null : idempotencyKey.trim();
134	        if (key != null) {
135	            Integer existingId = idempotencyKeys.get(key);
136	            if (existingId != null) {
137	                Owner original = this.clinicService.findOwnerById(existingId);
138	                if (original != null) {
139	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(original), HttpStatus.OK);
140	                }
141	                // The originally created owner is gone; forget the stale key and create afresh.
142	                idempotencyKeys.remove(key);
143	            }
144	        }
145	        HttpHeaders headers = new HttpHeaders();
146	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
147	        if (owner.getRegistrationDate() == null) {
148	            owner.setRegistrationDate(LocalDate.now());
149	        }
150	        // A supplied registration date may not be later than the server's current date.
151	        if (owner.getRegistrationDate().isAfter(LocalDate.now())) {
152	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
153	        }
154	        owner.setRegistrationDate(toBusinessDay(owner.getRegistrationDate()));
155	        LocalDate registrationDate = owner.getRegistrationDate();
156	        long ownersCreatedThatDay = this.clinicService.findAllOwners().stream()
157	            .map(Owner::getRegistrationDate)
158	            .filter(registrationDate::equals)
159	            .count();
160	        if (ownersCreatedThatDay >= 100) {
161	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
162	        }
163	        String address = normalizedAddress(owner);
164	        if (address == null) {
165	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
166	        }
167	        owner.setAddress(address);
168	        String telephone = telephoneNormalizer.normalize(owner.getTelephone());
169	        if (telephone == null) {
170	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
171	        }
172	        if (!telephoneNormalizer.hasValidNationalNumberLength(telephone)) {
173	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
174	        }
175	        owner.setTelephone(telephone);
176	        String email = owner.getEmail();
177	        if (email != null) {
178	            email = email.trim();
179	            if (!EMAIL_PATTERN.matcher(email).matches()) {
180	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
181	            }
182	            String domain = email.substring(email.indexOf('@') + 1).toLowerCase(Locale.ROOT);
183	            if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
184	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
185	            }
186	            owner.setEmail(email.toLowerCase(Locale.ROOT));
187	        }
188	        // A postcode is optional, but when supplied it must be four digits and valid for the
189	        // owner's city per the fixed region table; a city with no known region accepts any
190	        // 4-digit postcode. Reject an out-of-range or malformed postcode with 400.
191	        String postcode = owner.getPostcode();
192	        if (postcode != null) {
193	            if (!POSTCODE_PATTERN.matcher(postcode).matches()
194	                    || !cityRegionResolver.isPostcodeValidForCity(owner.getCity(), postcode)) {
195	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
196	            }
197	        }
198	        // The owner's telephone and email are now in their canonical, stored form.
199	        // The household id is deterministic: owners with the same normalized last name and
200	        // postcode share it automatically. Assign it unconditionally so the membership-level
201	        // ceiling can key off it; it no longer participates in duplicate detection, which now
202	        // rests solely on the identity key below.
203	        owner.setHouseholdId(householdResolver.householdId(owner));
204	        // Duplicate detection is the single identity key: a candidate is rejected only when its
205	        // whole identityKey (normalized telephone, lower-cased email and soundex of the last name)
206	        // collides with a non-deleted owner's. Two people sharing a household with different
207	        // telephones therefore derive different keys and are both admitted; the second is instead
208	        // flagged as a possible duplicate by the soft-match rule below.
209	        if (isDuplicateOwner(owner)) {
210	            return new ResponseEntity<>(HttpStatus.CONFLICT);
211	        }
212	        String cityKey = IdentityUtils.normalizeIdentity(owner.getCity());
213	        long ownersInCity = this.clinicService.findAllOwners().stream()
214	            .filter(existing -> IdentityUtils.normalizeIdentity(existing.getCity()).equals(cityKey))
215	            .count();
216	        if (ownersInCity >= 50) {
217	            return new ResponseEntity<>(HttpStatus.CONFLICT);
218	        }
219	        owner.setCustomerCode(customerCode(owner));
220	        owner.setNamesakeCount(namesakeCount(owner));
221	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
222	        owner.setBulkSignupWarning(ownersCreatedThatDay > 80);
223	        // Soft-match: the candidate has already cleared the hard-duplicate check, but its
224	        // identityKey may still differ from an existing owner's while their last names sound alike
225	        // (equal soundex) and their postcodes match — a likely re-registration of the same person
226	        // under a different telephone or email. When it does, it is created but flagged as a
227	        // possible duplicate of that existing owner; otherwise the flag is false and no reference
228	        // is recorded.
229	        Integer possibleDuplicateOf = possibleDuplicateOf(owner);
230	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
231	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
232	        this.clinicService.saveOwner(owner);
233	        if (key != null) {
234	            idempotencyKeys.put(key, owner.getId());
235	        }
236	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
237	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
238	            ownerMapper.membershipLevel(owner), owner.getMembershipNumber());
239	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
240	        headers.setLocation(UriComponentsBuilder.newInstance()
241	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
242	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
243	    }
244	
245	    /**
246	     * The owner's postal address in the single canonical form under which it is stored, or
247	     * {@code null} when the owner supplies no usable address. An owner may supply its address
248	     * in EITHER form: the structured {@code addressLine1} (with an optional {@code addressLine2})
249	     * is preferred, and the flat {@code address} remains accepted for backward compatibility.
250	     *
251	     * <p>Normalization by {@link AddressNormalizer} is applied to whichever fields are supplied.
252	     * When a non-blank {@code addressLine1} is present the owner's structured fields are replaced
253	     * with their normalized values (a blank or absent {@code addressLine2} is cleared to
254	     * {@code null}) and the returned address is composed as the normalized {@code addressLine1},
255	     * with a single space and the normalized {@code addressLine2} appended when present. Otherwise
256	     * the flat {@code address} is normalized and the structured fields are cleared. A blank result
257	     * (no usable address in either form) has no canonical form and is reported as {@code null} so
258	     * the caller can reject the request with 400.
259	     *
260	     * <p>This is the single point at which an owner's address is resolved and normalized on
261	     * create, so every rule keyed on the stored address reads the one value produced here.
262	     *
263	     * @param owner the owner about to be created
264	     * @return the canonical stored address, or {@code null} when the owner supplies none
265	     */
266	    private String normalizedAddress(Owner owner) {
267	        String rawLine1 = owner.getAddressLine1();
268	        if (rawLine1 != null && !rawLine1.isBlank()) {
269	            String line1 = addressNormalizer.normalize(rawLine1);
270	            String line2 = addressNormalizer.normalize(owner.getAddressLine2());
271	            owner.setAddressLine1(line1);
272	            owner.setAddressLine2(line2.isBlank() ? null : line2);
273	            return line2.isBlank() ? line1 : line1 + " " + line2;
274	        }
275	        owner.setAddressLine1(null);
276	        owner.setAddressLine2(null);
277	        String address = addressNormalizer.normalize(owner.getAddress());
278	        return address.isBlank() ? null : address;
279	    }
280	
281	    /**
282	     * Whether {@code candidate} collides with an already-registered owner under the single
283	     * identity rule enforced on create. This is the one point at which a new owner is
284	     * rejected as a duplicate (HTTP 409): all duplicate detection is consolidated into the
285	     * derived {@link OwnerMapper#identityKey identityKey} — the SHA-256 hex over the normalized
286	     * telephone, the lower-cased email (or an empty string when absent) and the soundex of the
287	     * last name, joined by '|'. The candidate clashes only when its WHOLE identityKey equals an
288	     * existing owner's; because the telephone is part of the key, two people sharing a household
289	     * (a like-sounding last name and postcode) with different telephones have different
290	     * identityKeys and are both allowed.
291	     *
292	     * <p>The candidate arrives with its telephone and email already normalized, and each existing
293	     * owner is stored in the same canonical form, so an identityKey match means the two owners are
294	     * genuinely the same identity.
295	     *
296	     * @param candidate the fully-normalized owner about to be created
297	     * @return {@code true} if an existing owner already occupies the candidate's identityKey
298	     */
299	    private boolean isDuplicateOwner(Owner candidate) {
300	        String identityKey = OwnerMapper.identityKey(candidate);
301	        return this.clinicService.findAllOwners().stream()
302	            .filter(existing -> !existing.isDeleted())
303	            .map(OwnerMapper::identityKey)
304	            .anyMatch(identityKey::equals);
305	    }
306	
307	    /**
308	     * The id of the existing owner the fully-normalized {@code candidate} soft-matches, or
309	     * {@code null} when there is none. A soft match is an owner whose whole identityKey differs
310	     * from the candidate's (so it is not a hard duplicate) yet whose last name sounds alike (equal
311	     * {@link IdentityUtils#soundex soundex}) and whose postcode matches — a likely re-registration
312	     * of the same person under a different telephone or email. Both must supply a postcode for a
313	     * match to be possible; when several existing owners qualify the lowest id is returned so the
314	     * result is deterministic.
315	     *
316	     * @param candidate the fully-normalized owner about to be created
317	     * @return the matching existing owner's id, or {@code null} if the candidate is no soft match
318	     */
319	    private Integer possibleDuplicateOf(Owner candidate) {
320	        String postcode = candidate.getPostcode();
321	        if (postcode == null || postcode.isBlank()) {
322	            return null;
323	        }
324	        String identityKey = OwnerMapper.identityKey(candidate);
325	        String lastNameSoundex = IdentityUtils.soundex(candidate.getLastName());
326	        return this.clinicService.findAllOwners().stream()
327	            .filter(existing -> !existing.isDeleted()
328	                && !identityKey.equals(OwnerMapper.identityKey(existing))
329	                && IdentityUtils.soundex(existing.getLastName()).equals(lastNameSoundex)
330	                && postcode.equals(existing.getPostcode()))
331	            .map(Owner::getId)
332	            .filter(java.util.Objects::nonNull)
333	            .min(Integer::compareTo)
334	            .orElse(null);
335	    }
336	
337	    /**
338	     * Build the customer code assigned to {@code owner} on create, formatted
339	     * {@code '<REGION>-<HASH8>'}: REGION is the region code derived from the owner's postcode
340	     * (falling back to the city) via {@link CityRegionResolver}, and HASH8 is the first eight
341	     * upper-case hex characters of the SHA-256 digest of the normalized telephone concatenated
342	     * with the last name (e.g. 'NSW-1A2B3C4D'). There is no per-city sequence.
343	     *
344	     * <p>When the computed code collides with an already-registered owner's customerCode it is
345	     * de-duplicated by appending {@code '-<n>'} with the smallest {@code n} of 2 or more that
346	     * makes it unique (e.g. 'NSW-1A2B3C4D-2'), and the unique code is returned.
347	     */
348	    private String customerCode(Owner owner) {
349	        String region = cityRegionResolver.regionFor(owner.getCity(), owner.getPostcode());
350	        String hash8 = HashUtils.sha256HexPrefix(owner.getTelephone() + owner.getLastName(), 8);
351	        String base = region + "-" + hash8;
352	        java.util.Set<String> existing = this.clinicService.findAllOwners().stream()
353	            .map(Owner::getCustomerCode)
354	            .filter(java.util.Objects::nonNull)
355	            .collect(java.util.stream.Collectors.toSet());
356	        if (!existing.contains(base)) {
357	            return base;
358	        }
359	        int n = 2;
360	        while (existing.contains(base + "-" + n)) {
361	            n++;
362	        }
363	        return base + "-" + n;
364	    }
365	
366	    /**
367	     * The number of existing owners that share {@code owner}'s firstName and lastName,
368	     * compared case-insensitively. The candidate is not yet stored at the point this is
369	     * assigned, so it does not count itself. This is the value stored as the owner's
370	     * namesakeCount on create.
371	     */
372	    private int namesakeCount(Owner owner) {
373	        return (int) this.clinicService.findAllOwners().stream()
374	            .filter(existing -> owner.getFirstName().equalsIgnoreCase(existing.getFirstName())
375	                && owner.getLastName().equalsIgnoreCase(existing.getLastName()))
376	            .count();
377	    }
378	
379	    /** Fixed list of public holidays that a registration date must roll past. */
380	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
381	        LocalDate.of(2026, 1, 1),
382	        LocalDate.of(2026, 1, 26),
383	        LocalDate.of(2026, 4, 25),
384	        LocalDate.of(2026, 12, 25),
385	        LocalDate.of(2026, 12, 28));
386	
387	    /**
388	     * Roll a registration date forward to the next business day: a Saturday, Sunday
389	     * or listed public holiday advances one day at a time until it lands on a weekday
390	     * that is not a public holiday. A plain weekday is returned unchanged.
391	     */
392	    private static LocalDate toBusinessDay(LocalDate date) {
393	        while (isWeekend(date) || PUBLIC_HOLIDAYS.contains(date)) {
394	            date = date.plusDays(1);
395	        }
396	        return date;
397	    }
398	
399	    private static boolean isWeekend(LocalDate date) {
400	        return switch (date.getDayOfWeek()) {
401	            case SATURDAY, SUNDAY -> true;
402	            default -> false;
403	        };
404	    }
405	
406	    /**
407	     * Build the membership number assigned on create, formatted
408	     * {@code '<customerCode>-M<YY>'} where YY is the last two digits of the fiscal year of the
409	     * business-day-adjusted {@code registrationDate} (the fiscal year starts on 1 July), e.g.
410	     * 'NSW-1A2B3C4D-M26'.
411	     */
412	    private static String membershipNumber(String customerCode, LocalDate registrationDate) {
413	        String yy = String.format("%02d", OwnerMapper.fiscalYear(registrationDate) % 100);
414	        return customerCode + "-M" + yy;
415	    }
416	}
